UPDATE companies SET description='Green Mountain Tableworx operates showrooms in Concord, New Hampshire, and Smithfield, Rhode Island, producing custom live-edge, river, and ocean tables from its New England workshop. The company fabricates dining tables, conference tables, coffee tables, benches, console tables, countertops, bar tops, floating shelves, and wall art. Each piece is built to order using an online estimator that captures wood species, dimensions, epoxy color, edge profile, and base style. Artisans handcraft the furniture from over 34 wood species — including black walnut, cherry, maple, white oak, hickory, and English walnut — and pair slabs with steel hairpin legs, solid-wood trestles, or proprietary pedestal bases such as the Haru and Summa models. Finished pieces are delivered and installed in homes throughout New England. Green Mountain Tableworx emphasizes a streamlined buying experience: the instant online estimator provides a price range in minutes, eliminating the need for an initial showroom visit, and the company handles delivery and in-home placement across the region.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom live edge table fabrication", "River table epoxy pouring", "Ocean table resin casting", "Custom furniture design and consultation", "Online configuration and instant quoting", "In-home delivery and installation", "Wood slab selection, milling, and finishing", "Custom base fabrication (steel and solid wood)", "Engraving and personalization"], "industries": [], "materials": ["Black Walnut", "Cherry", "Maple", "White Oak", "Hickory", "English Walnut", "Douglas Fir", "Epoxy resin", "Steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Instant online estimator that configures wood, dimensions, epoxy, edge, and base", "In-home delivery and installation anywhere in New England", "Over 34 domestic and exotic wood species in stock", "Handcrafted by New England artisans from slab selection to final finish", "Proprietary table base designs including Haru Pedestal, Wine Glass, Lithe Pedestal, and Summa"], "facts_used": ["Headquarters in Concord, NH and showroom in Smithfield, RI -> db", "Produces custom live edge, river, and ocean tables -> /", "Offers dining, conference, coffee, bench, console, countertop, bar top, shelf, and wall art -> /", "Online estimator for wood, dimensions, epoxy, edge, base -> /", "Over 34 wood species including Black Walnut, Cherry, Maple, White Oak, Hickory, English Walnut, Douglas Fir -> /", "Bases: steel hairpins, solid wood trestles, Haru Pedestal, Wine Glass, Lithe Pedestal, Summa -> /", "In-home delivery anywhere in New England -> /", "Handcrafted by artisans in New England -> /", "Customer testimonials referencing custom cocktail tray, end table, ocean dining table -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Handcrafted in New England.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='green-mountain-tableworx' AND approved AND profile IS NULL;
UPDATE companies SET description='Green Muscle Solar operates from Sun City, Arizona. The company was founded by co-owners Jim, Brent, Paula, and Jamell on the principle of treating customers right and putting their interests first. Leadership team members each bring over 11 years of hands-on solar experience, honed while working with the nation’s largest solar installer.

The firm provides solar installation, consulting, and service & maintenance for residential systems. Installation projects are overseen by a dedicated Project Manager rather than a commissioned sales representative, and Master Electricians supervise every install to ensure code compliance. Crews handle roof penetration sealing, conduit runs, wiring, and main-panel tie-ins. The service division troubleshoots production issues, performs preventative maintenance, and services out-of-warranty systems.

Green Muscle serves homeowners who have existing solar contracts, offering detailed production analysis, contract review, and system inspections. Its maintenance work targets previously installed systems that are out of warranty, correcting installation defects that affect output. Referrals from satisfied residential customers drive much of the business.

The company differentiates itself through an integrity-and-education approach, emphasizing real value over sales pressure. Rigorous installer training, direct project management, and a referral-based model reflect its founding belief that customer care builds lasting trust.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Solar installation", "Solar consulting", "Service & maintenance", "System inspection", "Warranty analysis", "Preventative maintenance", "Troubleshooting", "Roof penetration sealing", "Electrical panel tie-in", "Project management", "System design", "Permitting and utility coordination"], "industries": ["Solar energy", "Renewable energy", "Residential solar installation", "Solar maintenance services"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Project Manager oversees each project from design to utility interconnection", "Master Electricians supervise every installation", "Service and maintenance for out-of-warranty solar systems", "Detailed production analysis and contract review for existing systems", "Rigorous installer training and roof-penetration sealing with advanced technology"], "facts_used": ["Headquarters in Sun City, Arizona -> /", "Founded by co-owners Jim, Brent, Paula, Jamell -> /", "Leadership team has over 11 years experience each -> /about-us", "Services: installation, consulting, service & maintenance -> /", "Project Manager not commissioned sales rep -> /", "Master Electricians supervise installs -> /about-us", "Service for out-of-warranty systems -> /", "Detailed production analysis and contract review -> /", "Referral-based business -> /about-us", "Team includes installers, service technicians, project managers -> /", "LinkedIn URL -> db"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "We provide no pressure solutions for all of your solar needs. ... INSTALLATION ... Meet with an experienced Project Manager ... to review your solar options and pricing. ... SERVICE & MAINTENANCE ... We provide the best in-industry maintenance and service work for previously installed systems that are OUT of WARRANTY.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/green-muscle-solar/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='green-muscle-solar' AND approved AND profile IS NULL;
UPDATE companies SET description='Greene Textile Inc operates from Montebello, California, in the heart of Southern California''s textile corridor. The company was founded in 2001 by two brothers who had relocated from New York to California in the 1980s, joining a family network already established in the local textile trade. After two decades of working with yarn suppliers, knitting mills, and dye houses, the brothers launched their own venture from a small office above a knitting mill before expanding to their current Telegraph Road facility, which now houses a showroom, warehouse, and operations.

The firm specializes in knit-to-order production, maintaining a library of more than 4,000 fabric styles primarily in cotton. Its capabilities span yarn sourcing, custom knitting, and both piece and garment dyeing, allowing clients to develop unique colorways and finishes. The Montebello facility supports full vertical integration from yarn selection through finished fabric, and the company also carries an inventory of in-stock fabrics for immediate shipment.

Greene Textile serves clothing brands and small businesses across the apparel sector, providing custom-developed knits for fashion labels as well as low-minimum-order stock fabrics for emerging designers and garment-dye houses. Its customer base includes brands seeking domestic production with flexible volume requirements.

The company emphasizes a family-oriented approach to manufacturing, citing the principle that treating every partner like family underpins its operational philosophy. This culture, rooted in the founders'' early experience within the Southern California textile community, is presented as the foundation of its reliability and responsiveness.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Knit to order production", "Custom fabric knitting", "Fabric dyeing (piece and garment)", "Yarn sourcing", "In-stock fabric supply", "Custom fabric development", "Garment dyeing", "Piece dyeing", "Additional custom services"], "industries": ["Clothing brands", "Small businesses", "Apparel manufacturing", "Fashion"], "materials": ["Cotton"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Low minimum order quantities on in-stock fabrics", "Garment and piece dyeing for custom colorways", "Library of over 4,000 knit styles in cotton", "Domestic manufacturing in Southern California", "Family-oriented service culture"], "facts_used": ["Founded in 2001 -> /about", "Two brothers relocated from New York in 1980s -> /about", "Started in small office above knitting mill -> /about", "Current facility on Telegraph Road in Montebello -> /about", "Manufactures premium knit fabrics -> /about", "Library of over 4,000 styles using cotton -> products", "Specializes in yarn sourcing, knitting, dyeing custom fabrics -> description", "In-stock fabrics for low minimum order quantities -> description", "Garment dyeing and piece dyeing offered -> description", "Serves clothing brands and small businesses -> description", "Family-oriented manufacturing philosophy -> /about", "Headquarters Montebello, California -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Founded in 2001, Greene Textile has proudly manufactured premium knit fabrics right here in Southern California.", "founded_year": "2001", "employee_count": "", "cage_code