UPDATE companies SET description='Happy''s Gifts and Apparel operates from a home-based shop in Hazen, North Dakota, serving Mercer County and surrounding communities. The business was started about five years ago by Keith and Morgan, a husband-and-wife team who run the operation as a Christian, family-owned enterprise. Keith, a paramedic of over ten years, began with a miter saw crafting custom woodworking pieces for local customers; demand grew after they added a laser engraver and later an embroidery machine, turning a side project into a full-time custom shop.

The company provides custom embroidery, laser engraving and cutting, screen-printed and embroidered apparel (t‑shirts, polos, hats, hoodies), laser‑engraved stainless‑steel tumblers, and a range of promotional products such as keychains, coozies, trays, awards and magnets. All work is done in‑house with low minimum orders and wholesale pricing for volumes typically ranging from 10 to 100+ pieces. Free design proofs are offered on every project.

Primary customers include oil‑field crews, schools, churches, farms and local businesses in Beulah, Hazen, Stanton and Washburn. The shop also serves event organizers needing tradeshow giveaways, employee‑recognition awards and client‑appreciation gifts, as well as families seeking personalized keepsakes.

Happy''s emphasizes local, personal service: customers work directly with the makers, receive free design assistance, and can pick up orders in Hazen to avoid shipping delays. The owners highlight durable stitching and engraving built for North Dakota conditions, competitive wholesale rates, and the convenience of a single source for apparel, drinkware, awards and promotional items.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom embroidery", "Laser engraving and cutting", "Screen printing", "Branded apparel production (t\u2011shirts, polos, hats, hoodies)", "Custom tumbler and drinkware laser engraving", "Promotional product assembly (keychains, coozies, trays, awards, magnets)", "Custom award and sign fabrication", "Personalized gift manufacturing (wallets, piggy banks, keepsakes)", "Free design proofs", "Bulk and wholesale order fulfillment", "Local pickup and delivery"], "industries": ["Oil and gas", "Education", "Religious organizations", "Agriculture", "General business", "Events and tradeshows", "Consumer gifts"], "materials": ["Wood", "Leather", "Acrylic", "Stainless steel", "Apparel fabrics (cotton, polyester blends)"], "equipment": ["Laser engraver", "Embroidery machine", "Miter saw", "Screen printing equipment"], "volume": "Low minimums; bulk orders typically 10\u2013100+ pieces", "lead_time": "Fast local turnaround; same\u2011day or next\u2011day pickup available in Hazen", "tolerances": "", "built_on": ["Free design proofs on every order", "Fast local turnaround with in\u2011town pickup in Hazen", "Personal, hands\u2011on service \u2013 work directly with the makers", "Low minimums and wholesale pricing for 10\u2013100+ pieces", "One\u2011stop shop for embroidery, laser engraving, apparel, tumblers and promotional products"], "facts_used": ["Location: Hazen, ND (Mercer County) -> /", "Founders: Keith and Morgan -> /about", "Ownership: Family-owned, Christian, home-based -> /about", "Origin: Started ~5 years ago with miter saw, added laser engraver then embroidery machine -> /about", "Services: Custom embroidery, laser engraving/cutting, branded apparel, tumblers, promotional products -> /", "Processes: Embroidery, laser engraving/cutting, screen printing -> /", "Scale: Home-based shop, low minimums, wholesale pricing for 10-100+ pieces -> /", "Industries: Oil field crews, schools, churches, farms, businesses, events -> /", "Equipment: Laser engraver, embroidery machine, miter saw -> /about", "Materials: Wood, leather, acrylic, stainless steel, apparel fabrics -> /", "Differentiators: Free design proofs, fast local turnaround, personal service, wholesale pricing, one-stop shop -> /", "Headquarters: Hazen, ND (moved from Washburn) -> /about", "Company type: Contract manufacturer/job shop -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We specialize in custom embroidery, laser engraving/cutting, branded apparel (t-shirts, polos, hats), tumblers, promotional products, and unique gifts.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "Low minimums; flexible for 10\u2013100+ pieces", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='happy-s-gifts-and-apparel' AND approved AND profile IS NULL;
UPDATE companies SET description='Harbor Steel & Supply Corporation, headquartered in Prichard, West Virginia, has operated as a family-owned metal service center since 1952. The company was founded on principles of quality, reliability, and long-term customer relationships.

The company functions as a full-service metal supplier and processor across six U.S. locations. Its processing capabilities include tube and sheet laser cutting, beam cutting, oxy-fuel plate burning, saw cutting, cold saw cutting, plasma cutting, shearing, forming, and grinding. The facilities handle hot-rolled, stainless, and aluminum materials in bar, beam, tube, pipe, plate, and structural shapes, serving over 6,000 active customers.

Harbor Steel serves the metal industry throughout Michigan, southern Indiana, Ohio, Kentucky, and West Virginia.

