UPDATE companies SET description='Heisler Semiconductor LLC operates an advanced packaging and process development lab in Halethorpe, Maryland. The company was established as a US-based, engineering-led team focused on taking hard assembly and wafer-level processes from design review through qualified volume production.

The lab provides a full suite of advanced packaging services under one roof, including die attach, wire bonding, flip chip, hermetic sealing, wafer-level processing (lithography, TSV, deposition, etch, CMP, RDL), laser micromachining (micro-vias, dicing, singulation, marking), and comprehensive inspection and metrology (X-ray, 3D AOI, SEM, sub-micron metrology, cross-section failure analysis). The same engineering team handles circuit and hardware design, firmware development, and supply chain coordination, supporting builds from prototype through volume-qualified lots. Equipment includes BESI Datacon and Tresky die bonders, Keyence microscopy, Creative Electron X-ray inspection, and UV/IR laser systems.

Heisler serves high-reliability sectors such as aerospace and defense, medical and bio, RF/mmWave (including GaN and CMOS mixed-signal), and advanced sensors (fine-pitch, multi-die, 3D integration). Customers are typically companies building hardware where die placement within microns, thermal cycling survival, and first-lot qualification are critical.

The company differentiates itself with a data-driven, AI-native approach: designed experiments (DOE) replace trial-and-error, statistical process control and aggregated build data drive decisions, and AI surfaces drift and correlations to reduce iterations. All development and build work remains on US soil with a domestic supply chain, and detailed design rules and process data are shared under NDA.', certifications=ARRAY['MIL-STD']::text[], profile='{"capabilities": ["Die attach", "Wire bonding", "Flip chip", "Hermetic sealing", "Wafer-level processing (lithography, TSV, deposition, etch, CMP, RDL)", "Laser micromachining (micro-vias, dicing, singulation, marking)", "Inspection & metrology (X-ray, 3D AOI, SEM, sub-micron metrology, cross-section FA)", "Circuit and hardware design", "Firmware development", "RF evaluation board design", "Materials engineering (Silicon, Sapphire, AlN, Polyimide, Underfills, Thin-film)", "Reliability testing (thermal cycling, screening, hermetic test)", "Supply chain management (domestic sourcing, vendor coordination, turnkey, process transfer)", "Design of experiments (DOE) and statistical process control (SPC)", "AI-assisted process development and inspection software", "3D integration"], "industries": ["Aerospace & Defense", "Medical & Bio", "RF/mmWave", "Advanced Sensors"], "materials": ["Silicon", "Sapphire", "AlN", "Polyimide", "Underfills", "Thin-film"], "equipment": ["BESI Datacon die bonder", "Tresky precision die attach", "Keyence microscopy and metrology", "Creative Electron X-ray inspection", "UV 355nm laser micromachining", "IR 1064nm laser micromachining", "3D AOI", "SEM", "Sub-micron metrology", "Cross-section failure analysis"], "volume": "Prototype to volume", "lead_time": "", "tolerances": "\u00b12.5 \u00b5m at 3\u03c3 on BESI Datacon and Tresky platforms", "built_on": ["One engineering team owns the program from design review through qualified volume", "All development and build work performed on US soil with a domestic supply chain", "DOE-driven process development with SPC and aggregated data control", "AI-assisted iteration reduction and drift detection", "NDA-first engagement protecting customer design rules and yield data"], "facts_used": ["Location: Halethorpe, Maryland -> /about-us", "Advanced packaging services: die attach, wire bond, flip chip, hermetic sealing, wafer-level processing, laser micromachining, inspection & metrology -> /about-us and /", "Equipment: BESI Datacon, Tresky, Keyence, Creative Electron, UV/IR lasers -> /about-us", "Industries served: Aerospace & Defense, Medical & Bio, RF/mmWave, Advanced Sensors -> /", "Certification: MIL-STD -> / and /about-us", "Approach: DOE-driven, SPC, AI-assisted, US soil, NDA-first -> /about-us", "Volume range: prototype to volume -> /", "Tolerance: \u00b12.5 \u00b5m at 3\u03c3 -> /about-us", "Company type: Manufacturer (advanced packaging team) -> /about-us", "Headquarters: Halethorpe, Maryland -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Heisler Semiconductor is a US-based, engineering-led advanced packaging team. We take hard assembly and wafer-level processes from design review to qualified volume", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='heisler-semiconductor-llc' AND approved AND profile IS NULL;
