UPDATE companies SET description='High-Purity Silicon America Corporation (HSA) operates from Theodore, Alabama. The company was incorporated in 1996 as Mitsubishi Polycrystalline America Corporation, a wholly owned subsidiary of Mitsubishi Materials Corporation (MMC).

HSA manufactures polycrystalline silicon (polysilicon) in reduction furnaces at its Theodore facility. The plant also yields semiconductor-grade by-products — silicon tetrachloride and trichlorosilane — that serve as raw materials for epitaxial semiconductors and fiber-optic cables. Quality control relies on ultra-micro analysis equipment: floating-zone (Fz) conversion to single-crystal silicon for electrical-property measurement, photoluminescence (PL) for dopant detection down to parts-per-trillion levels, and ICP mass spectroscopy (ICP-MS) for metallic impurity screening. Additional analytical capabilities include gas chromatography (GC), Fourier-transform infrared spectroscopy (FTIR), and ICP atomic emission spectroscopy (ICP-AES).

The company supplies polysilicon and saline by-products to the semiconductor and fiber-optic industries. Its materials feed epitaxial wafer production and optical-cable manufacturing, where purity measured in parts per trillion is a prerequisite.

HSA describes its guiding philosophy as a "Continuum of Quality" — a never-ending process of improving processes, procedures, people, and products to become the industry''s preferred polysilicon supplier through product performance, technical service, and on-time delivery.', certifications=ARRAY['ISO 9001:2015','ISO 14001:2015']::text[], profile='{"capabilities": ["Polysilicon production", "Reduction furnace operation", "Floating zone (Fz) analysis", "Photoluminescence (PL) analysis", "ICP mass spectroscopy (ICP-MS)", "Gas chromatography (GC)", "Fourier transform infrared spectroscopy (FTIR)", "ICP atomic emission spectroscopy (ICP-AES)", "Semiconductor-grade saline product analysis", "Silicon tetrachloride production", "Trichlorosilane production"], "industries": ["Semiconductor", "Fiber optics", "Epitaxial semiconductors"], "materials": ["Polysilicon (polycrystalline silicon)", "Silicon tetrachloride", "Trichlorosilane", "Single crystalline silicon", "Phosphorus", "Arsenic", "Boron", "Aluminum"], "equipment": ["Reduction furnaces", "Floating zone equipment", "Photoluminescence equipment", "ICP-MS equipment", "Gas chromatography equipment", "FTIR equipment", "ICP-AES equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Incorporated in 1996 as Mitsubishi Polycrystalline America Corporation -> /", "Wholly owned by Mitsubishi Materials Corporation (MMC) -> /", "Recent addition to SUMCO group of companies -> /", "Headquartered in Theodore, Alabama -> db", "Produces polycrystalline silicon using reduction furnaces -> /quality", "Produces silicon tetrachloride and trichlorosilane as by-products -> /quality", "Uses floating zone (Fz) method for analysis -> /quality", "Uses photoluminescence (PL) for dopant detection down to ppt -> /quality", "Uses ICP-MS for metallic impurity analysis down to ppt -> /quality", "Uses GC, FTIR, ICP-AES, ICP-MS for saline product analysis -> /quality", "ISO 9001:2015 certified -> /quality", "ISO 14001:2015 certified -> /quality"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "The polycrystalline silicon produced in our factory''s reduction furnaces", "founded_year": "1996", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='high-purity-silicon-america-corporation' AND approved AND profile IS NULL;
UPDATE companies SET description='Hightec Solar, based in Michigan City, Indiana, was founded in 2010 with a mission to provide affordable, high-quality solar power systems.

The company manufactures solar panels in 36-, 60-, and 72-cell configurations, focusing on 12-volt modules for off-grid applications. It also operates as a distributor, supplying panels for projects ranging from single units to 100-megawatt installations.

The company positions itself as a Midwest distributor capable of fulfilling orders from one panel to utility-scale volumes.

Hightec Solar emphasizes its PTL certification as a mark of quality and reliability. It promotes American-made manufacturing, competitive pricing, and direct customer support as differentiators. The company states it was started to make high-performance solar systems accessible and to maintain a high level of customer satisfaction through straightforward communication.', certifications=ARRAY['PTL Certified']::text[], profile='{"capabilities": ["Solar panel manufacturing (36, 60, 72 cell)", "Solar panel distribution", "Off-grid solar system design consultation"], "industries": ["Off-grid solar", "Residential solar", "RV solar", "Commercial solar"], "materials": [], "equipment": [], "volume": "1 panel to 100 megawatts", "lead_time": "", "tolerances": "", "built_on": ["PTL certification for quality assurance", "American-made solar panel manufacturing", "Specialization in 12-volt off-grid solar panels", "Distribution capacity from single panels to 100 MW projects", "Direct customer support and system consultation"], "facts_used": ["Founded in 2010 -> /about-us", "Headquartered in Michigan City, Indiana -> /", "Manufactures 36, 60, 72 cell solar panels -> /", "Specializes in 12 volt off-grid solar panels -> /", "PTL Certified -> /about-us", "Claims to be one of Midwest''s largest panel distributors -> /", "Offers solutions from 1 panel to 100 megawatts -> /", "Customer testimonials from Jeremiah B., Tamara Fowler, Steve Lenhart -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Hightec Solar is an American solar panel manufacturer that is committed to manufacturing the highest quality solar panels available.", "founded_year": "2010", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='hightec-solar' AND approved AND profile IS NULL;
UPDATE companies SET description='Hillside Timber operates from Canistota, South Dakota, about 15 miles west of Sioux Falls along Highway 42. The company specializes in supplying live-edge and distinctive wood slabs, sourcing material from trees that are being removed for various reasons rather than harvested from standing timber. No founding year or ownership details are disclosed.

The business handles the full chain from sourcing to sales, offering milling, planing, sanding, and flattening services. Customers can purchase ready-to-use slabs — including Claro walnut, buckeye burl, maple burl, redwood burl, silver maple, and box elder — or bring their own logs for custom milling. Hillside Timber also distributes EcoPoxy bio-based epoxy resins for woodworking, art, construction, and marine applications.

The slabs are marketed toward furniture makers, woodworkers, and artisans building statement tables, feature walls, and custom pieces. The EcoPoxy line extends the customer base to builders and marine trades seeking sustainable coatings.

The company emphasizes its sustainable sourcing policy — only using wood from trees already coming down — as a core differentiator, alongside its ability to mill and prepare custom slabs on demand.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom slab milling", "Wood sourcing", "Planing", "Sanding", "Flattening", "Live edge slab sales", "EcoPoxy epoxy resin distribution"], "industries": ["Woodworking", "Art", "Construction", "Marine"], "materials": ["Claro Walnut", "Buckeye Burl", "Maple Burl", "Redwood Burl", "Silver Maple", "Box Elder", "EcoPoxy epoxy resins"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Sustainable sourcing: only wood from trees coming down", "Custom slab milling and planing service", "Pre-sanded and pre-flattened slabs ready for use", "Partnership with EcoPoxy for bio-based epoxy resins", "Live-edge slabs in rare species like Claro walnut and buckeye burl"], "facts_used": ["Location: Canistota, South Dakota -> db", "Business: premium supplier of live edge wood -> /about", "Specialties: sourcing, milling, planing, sales -> /about", "Sustainable sourcing: only harvest wood from trees coming down -> /about", "Custom slabs & milling service -> /", "Partnership with EcoPoxy for epoxy resins -> /", "Wood species offered: Claro Walnut, Buckeye Burl, Maple Burl, Redwood Burl, Silver Maple, Box Elder -> /", "Pre-sanded and pre-flattened slabs -> /", "Applications: woodworking, art, construction, marine -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Hillside Timber is a premium supplier of live edge and distinctive wood. Located 15 miles west on Highway 42 from Sioux Falls, our specialties include sourcing, milling, planing, and sales.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='hillside-timber' AND approved AND