UPDATE companies SET description='Hinrichs Fine Woods originated in 1993 in Roca, Nebraska, with the goal of producing higher-quality cabinetry than competitors offered. The company began by building custom cabinets and furniture from solid wood, using wood joinery instead of screws and nails and applying four coats of finish where three were typical. It also specialized in antique furniture restoration and repair from the start.

Today the shop operates from a 2,400-square-foot facility where it builds bookcases, entertainment centers, bath and kitchen cabinets, and other solid-wood furniture. All pieces feature inset, flush doors and drawers in traditional styles such as Mission, Shaker, and beaded face frames. Drawers are dovetailed for strength, and every surface receives four coats of finish inside and out. Restoration work is done by hand: old finishes are stripped manually rather than dipped, joints are repaired, and stains are color-matched to original pieces.

Projects range from new traditional-style kitchen cabinets to the repair of family antiques intended for another 80 years of service.

Hinrichs Fine Woods differentiates itself through its commitment to hand-crafted joinery, hand-applied finishes, and restoration methods that preserve the integrity of original pieces. The founder''s original quality standards—extra finish coats, wood joints over mechanical fasteners, and meticulous hand stripping—remain the benchmark for every project.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cabinetry", "Furniture making", "Furniture restoration", "Antique furniture restoration", "Custom kitchen cabinets", "Inset flush door construction", "Dovetail drawer construction", "Hand finishing (four coats)", "Hand stripping of finishes", "Color matching stains", "Mission style cabinetry", "Shaker style cabinetry", "Beaded face frames", "Bookcase construction", "Entertainment center construction", "Bath cabinet construction", "Solid wood furniture"], "industries": ["Residential construction", "Interior design", "Antique restoration", "Custom furniture", "Kitchen and bath"], "materials": ["Solid wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Four coats of finish applied inside and out on all pieces", "Wood joinery used instead of screws or nails", "Old finishes removed by hand stripping, not chemical dipping", "Dovetailed drawers for structural strength", "Inset, flush doors custom built for each project"], "facts_used": ["Founded 1993 -> /about", "2,400 sq ft facility -> /about", "Custom cabinetry, furniture, restoration -> /about, /", "Inset flush doors, dovetailed drawers -> /, /about", "Four coats finish inside and out -> /about", "Hand stripping not dipping -> /about", "Mission, Shaker, beaded face frames -> /", "Solid wood construction -> /about", "Headquarters Roca, Nebraska -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Today Hinrichs Fine Woods has grown into its current 2,400 square foot location. We are better equipped than ever with our experience and facilities to build bookcases, entertainment centers, bath and custom kitchen cabinets, and other solid wood furniture.", "founded_year": "1993", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='hinrichs-fine-woods-inc' AND approved AND profile IS NULL;
