UPDATE companies SET description='Holsen Solar was founded in 2018 in Fargo, North Dakota, by Ben Holsen. Holsen holds master electrician and contractor licenses in both North Dakota and Minnesota, and has operated without subcontractors since its inception.

The firm provides turnkey electrical and building contracting services across eastern North Dakota and western Minnesota, with commercial solar available statewide in both states. Its in-house team of 16 handles residential and commercial solar photovoltaic systems (rooftop, ground-mount, pole-mount, and tracking), Level 2 EV charger installations, permanent architectural LED lighting (Gemstone), commercial architectural lighting (Haven), battery energy storage (Tesla Powerwall, Franklin WH, EG4), and energy management systems (Span smart panels, Emporia monitoring). To date, the company has completed over 200 projects.

Customers include homeowners, farmers, small businesses, municipalities, apartment developers, and non-profit organizations such as charities and food banks. Recent projects include a 25 kW commercial rooftop array in Fargo, a full-roof commercial installation on a metal building in Moorhead, and a three-story residential Gemstone lighting project in Pelican Rapids, Minnesota.

Holsen Solar differentiates itself by performing all work under its own licenses — no subcontracting — and by guaranteeing transparent pricing, on-time completion, fully permitted and inspected installations, and ongoing post-installation support. The company cites local knowledge of utilities, cooperatives, inspectors, and weather as a core advantage built into every design.', certifications=ARRAY['UL Listed','Energy Star Certified Installer','Tesla Powerwall Certified','Span Panel Certified','Gemstone Lighting Certified','EV Charger Certified','PVIP Certified']::text[], profile='{"capabilities": ["Solar PV system design and installation (rooftop, ground mount, pole mount, tracking)", "EV charging station installation (Level 2 residential and commercial)", "Permanent architectural LED lighting installation (Gemstone)", "Commercial architectural lighting installation (Haven)", "Battery energy storage system installation (Tesla Powerwall, Franklin WH, EG4)", "Energy management system installation (Span smart panels, Emporia monitoring)", "Electrical permitting and inspection", "New construction electrical pre-wiring", "Emergency electrical service for existing customers", "Solar system monitoring and maintenance"], "industries": ["Residential", "Commercial", "Agricultural", "Municipal", "Non-profit (501(c)(3))", "Multi-family housing"], "materials": [], "equipment": ["Tesla Powerwall", "Franklin WH", "EG4", "Span smart panels", "Emporia monitoring", "Gemstone permanent lighting system", "Haven commercial lighting system"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["No subcontractors \u2014 all design, permitting, installation, and service performed by in-house licensed staff", "Master electrician and contractor licenses held in both North Dakota and Minnesota", "Every project fully permitted and inspected per local, state, and national electrical codes", "Transparent pricing with detailed cost breakdowns before work begins", "Post-installation support answered by company employees, not third parties"], "facts_used": ["Founded 2018 in Fargo, ND -> /about", "Ben Holsen founder and owner -> /about", "Team of 16 employees -> /about", "Master electrician and contractor licenses in ND and MN -> /about", "200+ projects completed -> /about and /", "Services: solar, EV chargers, Gemstone lighting, Haven lighting, energy storage, energy management -> /", "No subcontractors policy -> /about", "Transparent pricing, on-time completion, fully permitted, labor & materials warranty -> /", "Service area: Eastern ND, Western MN, commercial solar statewide -> / and /about", "Customer types: residential, commercial, farmers, municipalities, apartment developers, non-profits -> / and /about", "Specific projects: 25kW commercial rooftop Fargo, commercial array Moorhead, Gemstone lighting Pelican Rapids -> /", "Equipment: Tesla Powerwall, Franklin WH, EG4, Span, Emporia, Gemstone, Haven -> /", "Certifications: UL Listed, Energy Star Certified Installer, Tesla Certified, Span Certified, Gemstone Certified, EV Charger Certified, PVIP Certified -> / and /about", "Company type: licensed electrical and building contractor -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "We''re not a sales organization that hires subcontractors. We''re a licensed electrical and building contractor that does its own work \u2014 and stands behind it.", "founded_year": "2018", "employee_count": "16", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='holsen-solar' AND approved AND profile IS NULL;
