UPDATE companies SET description='Based in Tampa, Florida, Honest Components, Inc. operates as a woman-owned small business (WOSB) certified by the U.S. Small Business Administration. The company was built by a team with over 50 combined years of experience in electronic hardware and software, led by President Jackie Schwab, who brings more than 30 years of sales leadership and customer advocacy.

Honest Components specializes in sourcing and supplying new, obsolete, and hard-to-find board-level electronic components. Its line card includes over 50,000 part numbers from manufacturers such as AMD, Intel, and Texas Instruments, covering connectors, capacitors, microcontrollers, and memory chips. Every order undergoes third-party authentication at independent laboratories accredited to ISO/IEC 17025:2017 and AS6171, including visual inspection, X-ray imaging, decapsulation, solderability, and functional testing. The company manages the full procurement lifecycle — from vendor qualification and order management to logistics — and has supplied more than 200,000 authenticated components to date.

The distributor serves aerospace, defense, medical, and industrial customers, including OEMs and contract manufacturers with mission-critical requirements. It is ITAR registered and a member of the Government-Industry Data Exchange Program (GIDEP) to combat counterfeit parts, making it a qualified supplier for U.S. defense-related programs. Healthcare and medical equipment manufacturers also rely on its certified components for regulated applications.

Honest Components differentiates itself by bearing the cost of independent third-party testing on every order at no charge to the customer, backing each shipment with a 90-day form, fit, and function guarantee. Its WOSB certification supports supplier diversity goals, while its AS9120B and ISO 9001:2015 quality management system ensures traceability and compliance across the supply chain.', certifications=ARRAY['ISO 9001:2015','AS9120B','ITAR Registered','GIDEP Membership','WOSB (Women-Owned Small Business)']::text[], profile='{"capabilities": ["Component sourcing (legacy, obsolete, hard-to-find)", "Procurement management (vendor qualification, order management, logistics)", "Third-party laboratory testing (visual inspection, X-ray imaging, decapsulation, solderability, functional testing)", "Obsolete component management (last-time buy guidance, substitute identification)", "Component life cycle monitoring and end-of-life alerts", "Export compliance and international trade regulation navigation", "Counterfeit mitigation (GIDEP membership, supplier verification)", "Quality management per AS9120B and ISO 9001:2015"], "industries": ["Aerospace", "Defense", "Medical", "Healthcare", "Industrial"], "materials": ["Board-level electronic components", "Connectors", "Capacitors", "Microcontrollers", "Memory chips"], "equipment": [], "volume": "Small, medium, and high-volume requirements", "lead_time": "", "tolerances": "", "built_on": ["Independent third-party testing on every order at ISO/IEC 17025 and AS6171 accredited labs, at no cost to the customer", "90-day Form, Fit, and Function Guarantee on all components", "Woman-Owned Small Business (WOSB) certified by the SBA", "ITAR registered and GIDEP member for defense supply chain compliance", "Global sourcing network for obsolete and hard-to-find board-level components"], "facts_used": ["Headquarters: Tampa, Florida -> /about-us", "Woman-Owned Small Business (WOSB) certified by SBA -> /about-us", "Over 50 combined years of experience in electronic hardware and software -> /about-us", "President Jackie Schwab with 30+ years sales leadership -> /about-us", "Sources and supplies new, obsolete, hard-to-find board-level electronic components -> /", "Line card includes over 50,000 part numbers from AMD, Intel, Texas Instruments -> /", "Components include connectors, capacitors, microcontrollers, memory chips -> /", "Every order tested at ISO/IEC 17025:2017 and AS6171 accredited labs -> /", "Testing includes visual inspection, X-ray, decapsulation, solderability, functional testing -> /services", "Full procurement lifecycle management -> /services", "More than 200,000 authentic components supplied -> /", "Serves aerospace, defense, medical, industrial customers -> /about-us, /", "ITAR registered -> /about-us, /", "GIDEP member -> /about-us, /", "ISO 9001:2015 and AS9120B certified -> /about-us, /", "BBB Accredited -> /", "90-day Form, Fit, and Function Guarantee -> /about-us", "Export compliance navigation -> /, /services", "No-cost third-party testing on every order -> /, /services"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We source and supply new, obsolete, and hard-to-find board-level electronic components", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered", "Export compliance"], "languages": [], "social_links": [], "ownership_tags": ["Woman-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='honest-components-inc' AND approved AND profile IS NULL;
